-- Import généré par scripts/import_catalogue.py — édition 2.1.0 (2026-10-21), partie 1/3 activités.
-- Idempotent : relancer ne crée ni doublon ni nouvelle version si rien n'a changé. Les parties existantes
-- gardent leur copie de cartes et leur version de règles. Ne pas modifier à la main.

with src as (select * from jsonb_to_recordset($n$[
{"id":"complicite-confidences","n":1,"promise":"Des échanges qui partent du quotidien, des choix qui font sourire et des confidences que chacun choisit de partager.","title":"Complicité et confidences"},
{"id":"mots-repartie","n":2,"promise":"Des lettres à manipuler, des indices à inventer et le plaisir de comprendre comment l’autre pense.","title":"Mots et répartie"},
{"id":"dessin-creation","n":3,"promise":"Des ateliers tactiles où un trait maladroit devient une idée commune. Aucun niveau de dessin attendu.","title":"Dessin et création"},
{"id":"memoire-observation","n":4,"promise":"Un cabinet de curiosités : repérer, retenir, comparer et reconstruire des scènes claires sur petit écran.","title":"Mémoire et observation"},
{"id":"logique-codes","n":5,"promise":"Un atelier de casse-tête : des règles vérifiables, des indices justes et des solutions conservées côté serveur.","title":"Logique et codes"},
{"id":"plateaux-strategie","n":6,"promise":"Un salon de jeux de poche : vrais choix tactiques, pièces lisibles et manches avec une fin définie.","title":"Plateaux et stratégie"},
{"id":"cooperation-missions","n":7,"promise":"Deux écrans, des informations complémentaires et des actions qui ont besoin l’une de l’autre.","title":"Coopération et missions"},
{"id":"histoires-improvisation","n":8,"promise":"Un petit studio à deux : écrire, jouer des personnages, composer des scènes et conserver vos créations.","title":"Histoires et improvisation"}
]$n$::jsonb) as x(id text, title text, promise text, n int)),
up as (
  insert into public.game_categories (id, title, promise, sort, status, is_demo, family_no)
  select id, title, promise, n, 'published', false, n from src
  on conflict (id) do update set title = excluded.title, promise = excluded.promise, sort = excluded.sort,
    status = excluded.status, family_no = excluded.family_no
  where (game_categories.title, game_categories.promise, game_categories.sort, game_categories.status, game_categories.family_no)
    is distinct from (excluded.title, excluded.promise, excluded.sort, excluded.status, excluded.family_no)
  returning (xmax = 0) as inserted)
insert into public.catalogue_imports (content_version, report)
select $n$2.1.0$n$, jsonb_build_object('partie', $n$1/3$n$, 'section', $n$familles$n$,
  'ajouts', count(*) filter (where inserted), 'mises_a_jour', count(*) filter (where not inserted)) from up;

